const response = $input.first().json;
const workers = response.workers || [];

const healthReport = workers.map(worker => ({
  worker_id: worker.id,
  status: worker.status,
  cpu_usage: worker.cpu_usage || 0,
  memory_usage: worker.memory_usage || 0,
  active_jobs: worker.active_jobs || 0,
  queue_depth: worker.queue_depth || 0,
  last_heartbeat: worker.last_heartbeat,
  uptime: worker.uptime || 0
}));

const unhealthyWorkers = healthReport.filter(w => 
  w.status !== 'healthy' || 
  w.cpu_usage > 90 || 
  w.memory_usage > 90 ||
  (new Date() - new Date(w.last_heartbeat)) > 60000
);

return [{
  json: {
    total_workers: healthReport.length,
    healthy_workers: healthReport.filter(w => w.status === 'healthy').length,
    unhealthy_workers: unhealthyWorkers.length,
    workers: healthReport,
    unhealthy: unhealthyWorkers,
    timestamp: new Date().toISOString()
  }
}];

const health = $('Process Health Data').first().json;
const timeouts = $input.first().json;
const queueDepth = $('Check Queue Depth').first().json;

const warnings = [];

if (health.unhealthy_workers > 0) {
  warnings.push({
    type: 'worker_health',
    severity: 'high',
    message: `${health.unhealthy_workers} unhealthy workers detected`,
    details: health.unhealthy
  });
}

if (timeouts.timed_out_jobs && timeouts.timed_out_jobs.length > 0) {
  warnings.push({
    type: 'job_timeout',
    severity: 'high',
    message: `${timeouts.timed_out_jobs.length} jobs have timed out`,
    details: timeouts.timed_out_jobs
  });
}

if (queueDepth.total_pending > 100) {
  warnings.push({
    type: 'queue_depth',
    severity: 'medium',
    message: `Queue depth is high: ${queueDepth.total_pending} pending jobs`,
    details: queueDepth
  });
}

if (queueDepth.total_pending > 500) {
  warnings[warnings.length - 1].severity = 'high';
}

const totalWarnings = warnings.length;
const highSeverity = warnings.filter(w => w.severity === 'high').length;

return [{
  json: {
    warnings: warnings,
    total_warnings: totalWarnings,
    high_severity: highSeverity,
    health_summary: health,
    timestamp: new Date().toISOString()
  }
}];

